cat > src/server.js <<'EOF'
import http from 'node:http';
import { STATUS_CODES, reasonPhrase } from './status-codes.js';

function sendJson(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, reasonPhrase(statusCode), {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendError(res, statusCode) {
  sendJson(res, statusCode, { error: reasonPhrase(statusCode), status: statusCode });
}

export function handleRequest(req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');

  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return sendError(res, 405);
  }

  if (pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }

  if (pathname === '/status-codes') {
    return sendJson(res, 200, STATUS_CODES);
  }

  const match = pathname.match(/^\/status-codes\/(\d{3})$/);
  if (match) {
    const code = Number(match[1]);
    const phrase = reasonPhrase(code);
    return phrase ? sendJson(res, 200, { code, phrase }) : sendError(res, 404);
  }

  return sendError(res, 404);
}

export function createServer() {
  return http.createServer((req, res) => {
    try {
      handleRequest(req, res);
    } catch (err) {
      console.error(err);
      if (!res.headersSent) sendError(res, 500);
      else res.destroy(err);
    }
  });
}

// Start only when run directly (not when imported by tests).
if (import.meta.url === `file://${process.argv[1]}`) {
  const port = Number(process.env.PORT) || 3000;
  const server = createServer();
  server.listen(port, () => console.log(`Listening on http://localhost:${port}`));

  const shutdown = () => server.close(() => process.exit(0));
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
EOF
cat > test/status-codes.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { STATUS_CODES, reasonPhrase, statusClass } from '../src/status-codes.js';

test('common codes map to standard phrases', () => {
  assert.equal(reasonPhrase(200), 'OK');
  assert.equal(reasonPhrase(404), 'Not Found');
  assert.equal(reasonPhrase(500), 'Internal Server Error');
});

test('unknown codes return undefined', () => {
  assert.equal(reasonPhrase(306), undefined);
  assert.equal(reasonPhrase(999), undefined);
  assert.equal(reasonPhrase('toString'), undefined);
});

test('table is frozen and keys are valid 3-digit codes', () => {
  assert.ok(Object.isFrozen(STATUS_CODES));
  for (const key of Object.keys(STATUS_CODES)) {
    assert.match(key, /^[1-5]\d\d$/);
  }
});

test('statusClass categorizes codes', () => {
  assert.equal(statusClass(101), 'informational');
  assert.equal(statusClass(204), 'success');
  assert.equal(statusClass(308), 'redirection');
  assert.equal(statusClass(429), 'client-error');
  assert.equal(statusClass(503), 'server-error');
  assert.equal(statusClass(600), undefined);
  assert.equal(statusClass(99), undefined);
});
EOF
cat > test/server.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../src/server.js';

let server;
let base;

before(async () => {
  server = createServer();
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

after(() => new Promise((resolve) => server.close(resolve)));

test('GET /health', async () => {
  const res = await fetch(`${base}/health`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { status: 'ok' });
});

test('GET /status-codes/:code', async () => {
  const res = await fetch(`${base}/status-codes/418`);
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), { code: 418, phrase: "I'm a Teapot" });
});

test('unknown code returns 404 with reason phrase', async () => {
  const res = await fetch(`${base}/status-codes/299`);
  assert.equal(res.status, 404);
  assert.equal(res.statusText, 'Not Found');
});

test('non-GET returns 405 with Allow header', async () => {
  const res = await fetch(`${base}/health`, { method: 'POST' });
  assert.equal(res.status, 405);
  assert.equal(res.headers.get('allow'), 'GET, HEAD');
});
EOF
cat > README.md <<'EOF'
# http-server

Minimal Node.js HTTP server (no dependencies) with a lookup table of HTTP status codes and reason phrases.

## Usage

```sh
npm start          # listens on PORT (default 3000)
npm run dev        # restarts on file changes
npm test
```

## Endpoints

| Method | Path                  | Description                         |
| ------ | --------------------- | ----------------------------------- |
| GET    | `/health`             | Health check                        |
| GET    | `/status-codes`       | Full status-code → phrase table     |
| GET    | `/status-codes/:code` | Phrase for one code (404 if unknown) |

## Status codes module

```js
import { STATUS_CODES, reasonPhrase, statusClass } from './src/status-codes.js';

reasonPhrase(404); // 'Not Found'
statusClass(503);  // 'server-error'
```

Phrases follow the IANA registry / RFC 9110 (e.g. 413 is "Content Too Large", 422 is "Unprocessable Content").
